<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free VAT Calculator Online','description'=>'Calculate VAT amount and price including or excluding VAT.','url'=>'https://smarttoolz.in/tools/vat-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>VAT Calculator</h1><p>Calculate VAT instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Amount<input id="a" type="number" value="1000"></label><label>VAT %<input id="v" type="number" value="18"></label><button id="go" class="tool-btn">Calculate VAT</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let A=+a.value,V=+v.value,t=A*V/100;o.textContent=`VAT: ${t.toFixed(2)} · Total: ${(A+t).toFixed(2)}`}</script><?php smarttoolz_tool_page_end(); ?>